#!/usr/bin/env bash
set -euo pipefail
[[ -d .git && -f pubspec.yaml && -f desktop/hyper_player/VISUAL_ALIGNMENT_6.md && -f desktop/hyper_player/lib/screens/playback_sheets.dart ]] || { echo 'Run in your repository root after the sixth Android visual-alignment update.' >&2; exit 1; }
python3 - <<'VISUAL_GROUP_SEVEN'
from pathlib import Path
import base64
files = {
'desktop/hyper_player/lib/main.dart': '',
'desktop/hyper_player/lib/screens/track_sheet.dart': '',
'desktop/hyper_player/test/track_sheet_test.dart': '',
'desktop/hyper_player/VISUAL_ALIGNMENT_7.md': '',
}
for name, data in files.items():
    p = Path(name)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(base64.b64decode(data))
print('Android-style Audio track and Subtitles panels installed. Android unchanged.')
VISUAL_GROUP_SEVEN
